    def _get_swap_exps(size: int) -> list[tuple[int, int]]:
        """Generate (u, v) pairs where v-u is often coprime to size."""
        pairs = set()

        # 1. Doubling pattern (strongest heuristic)
        # u, 2u
        for u in range(1, size):
            # Limit search space for larger lattices
            if size > 30 and u > 15: continue

            v = (2 * u) % size
            if v != 0 and v != u:
                pairs.add(tuple(sorted((u, v))))

        # 2. Coprime Gap pattern (new heuristic)
        # u, u + gap, where gcd(gap, size) == 1
        # This encourages mixing across subgroups
        bases = [1, 2, 3, 4]
        gaps = [g for g in range(1, size) if math.gcd(g, size) == 1]
        # Limit gaps for large lattices
        if len(gaps) > 8:
             gaps = [g for g in gaps if g < 15 or g > size - 15]

        for u in bases:
            for gap in gaps:
                v = (u + gap) % size
                if v != 0 and v != u:
                    pairs.add(tuple(sorted((u, v))))

        return sorted(list(pairs))

