    def _get_cm_triples(size: int) -> list[list[tuple[int, int]]]:
        triples = []

        # 1. Modular multiples: 1 + z^u + z^(k*u)
        # k=2 (doubling) is standard. k=3, 4, 5 are also good.
        multipliers = [2, 3, 4, 5]

        # Iterate u: Focus on units and small divisors
        seeds = [u for u in range(1, size) if math.gcd(u, size) == 1]
        # Add a few small non-units
        for i in range(2, 5):
            if i < size and i not in seeds: seeds.append(i)

        for u in seeds:
            for k in multipliers:
                v = (k * u) % size
                if v != 0 and v != u:
                    triples.append([(0,0), (u,0), (v,0)]) # Format for x-terms

        # 2. Symmetric/Palindromic-like: 1 + z^u + z^(size-u)
        # Often creates good distance properties
        for u in range(1, size // 2):
             v = (size - u) % size
             if v != 0 and v != u:
                 triples.append([(0,0), (u,0), (v,0)])

        return triples
