    def _get_cm_triples(size: int) -> list[list[tuple[int, int]]]:
        triples = []
        seen_t = set()

        def _add_t(u, v):
            t = tuple(sorted([(0,0), (u,0), (v,0)]))
            if t not in seen_t:
                seen_t.add(t)
                triples.append(list(t))

        # 1. Divisor codes: 1 + z^k + z^2k where k | size
        # This captures the 1+x^5+x^10 pattern in ell=15
        divisors = [d for d in range(1, size) if size % d == 0]
        for d in divisors:
            v = (2 * d) % size
            if v != 0 and v != d:
                _add_t(d, v)

        # 2. Unit Doubling/Tripling: 1 + z^u + z^ku
        # k=2, 3, 4. u is a unit.
        units = [u for u in range(1, size) if math.gcd(u, size) == 1]
        for u in units:
            for k in [2, 3, 4, 5]:
                v = (k * u) % size
                if v != 0 and v != u:
                    _add_t(u, v)

        # 3. Symmetric: 1 + z^u + z^(size-u)
        for u in range(1, size // 2 + 1):
             v = (size - u) % size
             if v != 0 and v != u:
                 _add_t(u, v)

        return triples
