    import math

    def _unit_range(size: int, limit: int) -> list[int]:
        # Return units AND divisors to capture structural scalings
        res = []
        for u in range(1, min(size, limit) + 1):
            if math.gcd(u, size) == 1 or size % u == 0:
                res.append(u)
        return sorted(list(set(res)))
